<template><view class="page"><view class="head"><text class="eyebrow">AI 智能助手</text><text class="title">碳宝AI</text><text class="subtitle">有什么问题都可以问我，不限于碳排放和减碳计算。</text></view><view class="assistant card"><view class="assistant-icon">✦</view><text class="assistant-title">你好，我是碳宝AI</text><text class="muted">可以聊天、咨询、写方案，也可以帮你分析碳相关问题。</text></view><view class="examples"><text class="examples-title">{{roleLabel}}示例问题</text><view v-for="item in examples" :key="item" class="example" @tap="content=item">{{item}}</view></view><view class="input-wrap"><textarea class="input" placeholder="输入你想咨询的内容，话题不限..." v-model="content"/><view class="primary-btn" :class="loading?'disabled':''" @tap="ask">{{loading?'思考中...':'发送咨询'}}</view></view><view v-if="reply" class="card result"><text class="muted">碳宝AI回复</text><text class="report">{{reply}}</text></view></view></template>
<script>
import {callCloud} from '../../common/cloud.js'
import {toast} from '../../common/mock.js'
const exampleMap={personal:['我每天骑行 5 公里，大约能减少多少碳排放？','如何制定一周低碳生活计划？','帮我写一份环保活动报名说明','今天心情不好，可以陪我聊聊吗？'],enterprise:['如何设计低碳商品宣传文案？','帮我策划一次校园环保活动','如何分析商品兑换和库存数据？','帮我写一份企业环保合作方案'],campus:['如何降低校园宿舍区的用电量？','帮我设计一次校园垃圾分类活动','如何写校园碳排放分析报告？','帮我制定学生低碳积分审核规则']}
export default {data(){return{role:'personal',roleLabel:'个人端',content:'',reply:'',loading:false}},computed:{examples(){return exampleMap[this.role]||exampleMap.personal}},onShow(){const user=uni.getStorageSync('user_session')||{};this.role=user.role||uni.getStorageSync('user_identity')||'personal';this.roleLabel=this.role==='enterprise'?'企业端':this.role==='campus'?'校园端':'个人端'},methods:{async ask(){if(!this.content.trim())return toast('请输入你想咨询的内容');const userId=uni.getStorageSync('user_session')?.id;if(!userId)return toast('请先登录');this.loading=true;try{const result=await callCloud('ai-carbon-advice',{content:this.content,userId,role:this.role});this.reply=result.reply||'暂时没有收到回复';toast('碳宝AI已回复')}catch(error){toast(error.message||'咨询失败')}finally{this.loading=false}}}}
</script>
<style lang="scss">@import '../../common/portal.scss';.assistant{text-align:center;padding:42rpx 28rpx}.assistant-icon{display:flex;align-items:center;justify-content:center;width:96rpx;height:96rpx;margin:0 auto 20rpx;border-radius:50%;background:#d6e6e3;color:#006d37;font-size:50rpx}.assistant-title{display:block;margin-bottom:12rpx;font-size:32rpx;font-weight:700}.examples{margin-top:26rpx}.examples-title{display:block;margin:0 4rpx 14rpx;color:#181c1c;font-size:28rpx;font-weight:700}.example{margin-bottom:12rpx;padding:20rpx 24rpx;border-radius:18rpx;background:#fff;color:#53615f;font-size:24rpx;box-shadow:0 6rpx 18rpx rgba(0,78,42,.05)}.input-wrap{margin-top:24rpx}.input{height:180rpx;margin-bottom:20rpx}.disabled{opacity:.6}.result{margin-top:24rpx}.report{display:block;margin-top:18rpx;color:#53615f;font-size:25rpx;line-height:1.7;white-space:pre-wrap}</style>
